SELECT * FROM system_heartbeat_record
AND DATE_FORMAT(heartbeat_time, '%Y-%m-%d') >= #{pageForm.startDate}
AND DATE_FORMAT(heartbeat_time, '%Y-%m-%d') <= #{pageForm.endDate}
AND (INSTR(project_path,#{pageForm.keywords}) or INSTR(server_ip,#{pageForm.keywords}) or INSTR(process_no,#{pageForm.keywords}))
order by heartbeat_time desc
